-- ============================================================-- FIX: Squadron creation RLS deadlock + profiles.squadron sync-- ============================================================-- 1. Make squadron creation functions SECURITY DEFINER--    so triggers can bypass RLS when creating default ranks--    and adding the creator as the first member.-- ============================================================CREATE OR REPLACE FUNCTION public.create_default_squadron_ranks(squadron_id integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINERAS $function$BEGIN  INSERT INTO public.squadron_ranks (squadron_id, name, sort_order, is_default, can_manage_projects, can_manage_members, can_manage_ranks, can_edit_squadron)  VALUES    (squadron_id, 'Командир эскадрильи', 1, true, true, true, true, true),    (squadron_id, 'Заместитель командира', 2, true, true, true, false, false),    (squadron_id, 'Офицер', 3, true, true, true, false, false),    (squadron_id, 'Ветеран', 4, true, true, false, false, false),    (squadron_id, 'Пилот', 5, true, false, false, false, false);END;$function$;CREATE OR REPLACE FUNCTION public.create_default_voice_rooms(squadron_id integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINERAS $function$BEGIN  INSERT INTO public.squadron_voice_rooms (squadron_id, name, description, is_officer_only, sort_order)  VALUES    (squadron_id, 'Общий канал', 'Общий голосовой канал для всех пилотов', false, 1),    (squadron_id, 'Офицерский канал', 'Голосовой канал для офицеров', true, 2),    (squadron_id, 'Оперативный канал', 'Канал для оперативных задач', false, 3);END;$function$;CREATE OR REPLACE FUNCTION public.on_squadron_created() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINERAS $function$DECLARE  cmdr_rank_id INTEGER;BEGIN  PERFORM public.create_default_squadron_ranks(NEW.id);  PERFORM public.create_default_voice_rooms(NEW.id);  SELECT id INTO cmdr_rank_id FROM public.squadron_ranks    WHERE squadron_id = NEW.id AND name = 'Командир эскадрильи';  IF cmdr_rank_id IS NOT NULL THEN    INSERT INTO public.squadron_members (squadron_id, user_id, rank_id)    VALUES (NEW.id, NEW.created_by, cmdr_rank_id);  END IF;  RETURN NEW;END;$function$;-- ============================================================-- 2. Sync profiles.squadron with squadron_members-- ============================================================CREATE OR REPLACE FUNCTION public.sync_profile_squadron_on_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINERAS $function$BEGIN  UPDATE public.profiles    SET squadron = (SELECT name FROM public.squadrons WHERE id = NEW.squadron_id)    WHERE id = NEW.user_id;  RETURN NEW;END;$function$;CREATE OR REPLACE FUNCTION public.sync_profile_squadron_on_delete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINERAS $function$BEGIN  UPDATE public.profiles    SET squadron = NULL    WHERE id = OLD.user_id;  RETURN OLD;END;$function$;DROP TRIGGER IF EXISTS trg_sync_profile_squadron_insert ON public.squadron_members;CREATE TRIGGER trg_sync_profile_squadron_insert  AFTER INSERT ON public.squadron_members  FOR EACH ROW  EXECUTE FUNCTION public.sync_profile_squadron_on_insert();DROP TRIGGER IF EXISTS trg_sync_profile_squadron_delete ON public.squadron_members;CREATE TRIGGER trg_sync_profile_squadron_delete  AFTER DELETE ON public.squadron_members  FOR EACH ROW  EXECUTE FUNCTION public.sync_profile_squadron_on_delete();-- ============================================================-- 3. Back-fill profiles.squadron for existing members-- ============================================================UPDATE public.profiles pSET squadron = sq.nameFROM public.squadron_members smJOIN public.squadrons sq ON sq.id = sm.squadron_idWHERE sm.user_id = p.id  AND p.squadron IS DISTINCT FROM sq.name;-- Clear squadron for users who left all squadronsUPDATE public.profiles pSET squadron = NULLWHERE p.squadron IS NOT NULL  AND NOT EXISTS (SELECT 1 FROM public.squadron_members sm WHERE sm.user_id = p.id);